Let $A, D, s,N\in{\mathbb N}$, and let $\ell$ be a power of 2. Let $I$ be a finite indexing set, and let $H_{ji}\subseteq [\pm AN]^D$ be symmetric
   multisets for each $i\in I$ and $j\in[s]$. Then for all $1$-bounded functions $f:{\mathbb Z}^D\to{\mathbb C}$ supported on $[N]^D$, the bound
    \begin{align*}
        \mathbb{E}_{i\in I}\left\Vert f\right\Vert_{H_{1i}, \ldots, H_{si}}^{2^{s}}\geq \delta N^D
    \end{align*}
    implies that
    \begin{align}
        \mathbb{E}_{\substack{k_1, \ldots, k_t\in I}}\left\Vert f\right\Vert_{\{H_{j k_{i_1}}+\cdots + H_{j k_{i_{\ell}}}:\ j\in[s],\ 1\leq i_1<\cdots < i_{\ell}\leq t\}}^{2^d}\gg_{A, D, \ell, s} \delta^{O_{\ell, s}(1)} N^D,
    \end{align}
    for some $t=O_{\ell, s}(1)$, where $d$ is the degree of the box norms on the left-hand side.

Let $d, r, s\in{\mathbb N}$ with $d\leq r$, and let $\ell$ be a power of $2$. There exists a positive integer $t=O_{\ell, r, s}(1)$ such that the following holds.  Let $\delta>0$ and $D, H, M, N, V\in{\mathbb N}$ satisfy $H^d M V \leq N$, and let ${\textbf{C}}_1, \ldots, {\textbf{C}}_s\in{\mathbb Z}^D[{\underline{h}}]$ be polynomials of degree at most $d$ with coefficients of size at most $V$.  Then for all $1$-bounded functions $f:{\mathbb Z}^D\to{\mathbb C}$ supported on $[N]^D$, the bound
    \begin{align}
        \mathbb{E}_{{\underline{h}}\in[\pm H]^r}\left\Vert f\right\Vert_{{\textbf{C}}_1({\underline{h}})\cdot[\pm M], \ldots, {\textbf{C}}_s({\underline{h}})\cdot[\pm M]}^{2^s}\geq \delta N^D
    \end{align}
    implies that
        \begin{align*}
        \mathbb{E}_{\substack{h_{lk_1\cdots k_l}\in[\pm H]:\\ l\in[r],\; k_1, \ldots, k_r\in[t]}}
        \left\Vert f\right\Vert_{\substack{\{\sum_{i_1, \ldots, i_r=1}^{\ell}{\textbf{C}}_j(h_{1k_{1i_1}}, \ldots, h_{rk_{1i_1}\cdots k_{ri_r}})\cdot[\pm M]:\\ j\in[s],\; {\underline{k}} \in {\mathcal K}
 \}}}^{2^{w}} \gg_{D, \ell, r, s} \delta^{O_{\ell, r, s}(1)} N^D,
    \end{align*}
    where ${\mathcal K}={\mathcal K}_{t,\ell,r}$ and $w$ is the degree of the box norms appearing.

Let $\eta>0$, let $\ell, r, s, t\in{\mathbb N}$ with $3\leq\ell\leq t$, and let $H, M\in{\mathbb N}$ with $H\leq M$. Let ${\mathcal K} = {\mathcal K}_{t, \ell, r}$ be as in (45), and for each $l\in[r]$, let ${\mathcal H}_l:={\mathcal H}_{l,\eta}$ be as in (46). Then 
        \begin{multline*}
        \max_{\substack{n_{j{\underline{k}}{\underline{u}}}\in{\mathbb Z}:\; j\in[s],\\ {\underline{k}}\in{\mathcal K},\; {\underline{u}}\in\{0,1\}^r}}\;\mathbb{E}_{\substack{m_{j{\underline{k}} i_1\cdots i_r}\in[\pm M]:\\ j\in[s],\; {\underline{k}}\in{\mathcal K},\; i_1, \ldots,  i_r\in[\ell]}}
                \mathbb{E}_{\substack{h_{lk_{1}\cdots k_{l}}\in[\pm H]:\\  k_1, \ldots, k_r\in[t],\; l\in[r]}}\; \Bigl( \prod_{l\in[r]}\mathbf{1}_{{\mathcal H}_l}((h_{lk_{1}\cdots k_{l}})_{k_1, \ldots, k_l \in [t]}) \Bigr)\\
        \prod_{j\in[s]}\; \prod_{\substack{{\underline{k}}\in{\mathcal K}}}\prod_{\substack{{\underline{u}}\in\{0,1\}^r
        }} \mathbf{1}\Bigl( \sum\limits_{i_1, \ldots, i_r\in[\ell]} h_{1k_{1i_1}}^{u_1} \cdots h_{rk_{1i_1}\cdots k_{ri_r}}^{u_r}m_{j{\underline{k}} i_1\cdots i_r} = n_{j{\underline{k}}{\underline{u}}} \Bigr)\\
        \ll_{\ell, r, s, t} \eta^{-O_{\ell, r, s,t}(1)}  M^{-2^{r}s|{\mathcal K}|}H^{-r2^{r-1}s|{\mathcal K}|}.
    \end{multline*}
(Here, the superscript $u$'s are exponents, not indices.)

Let $r,s \in {\mathbb N}$.  There exists a positive integer $t=O_{r, s}(1)$ such that the following holds.  Let $d, D, H, M, N, V\in{\mathbb N}$ and $\delta>0$ satisfy
    \begin{align*}
        d\leq r,\quad \delta^{-O_{\ell, r, s}(1)}\ll_{D, r, s} H\leq M\quad \textrm{and}\quad H^d M V\leq N,
    \end{align*}
    and let ${\textbf{C}}_1, \ldots, {\textbf{C}}_s\in{\mathbb Z}^D[h_1, \ldots, h_r]$ be multilinear polynomials ${\textbf{C}}_j({\underline{h}}) = \sum\limits_{{\underline{u}}\in\{0,1\}^r} {\boldsymbol{\gamma}}_{j{\underline{u}}}{\underline{h}}^{\underline{u}}$ of degree at most $d$ and with coefficients at most $V$.  Then for all $1$-bounded functions $f:{\mathbb Z}^D\to{\mathbb C}$ supported on $[N]^D$, the bound
    \begin{align*}
        \mathbb{E}_{{\underline{h}}\in[\pm H]^r}\left\Vert f\right\Vert_{{\textbf{C}}_1({\underline{h}})\cdot[\pm M], \ldots, {\textbf{C}}_s({\underline{h}})\cdot[\pm M]}^{2^s}\geq \delta N^D
    \end{align*}
        implies that
    \begin{align*}
        \left\Vert f\right\Vert_{E_1^{ t}, \ldots, E_s^{ t}}^{2^{st}}\gg_{D, r, s}\delta^{O_{r, s}(1)}N^{D},
    \end{align*}
    where
    \begin{align*}
        E_j = \sum_{{\underline{u}}\in\{0,1\}^d}{\boldsymbol{\gamma}}_{j{\underline{u}}}\cdot [\pm H^{|{\underline{u}}|+1}].
    \end{align*}

Let $d, \ell\in{\mathbb N}$. There exist positive integers $r, s=O_{d, \ell}(1)$ such that the following holds.  Let $\delta>0$ and $D, H, K, M, N,\in{\mathbb N}$ satisfy $H, M\ll_{d, D, \ell}\delta^{O_{d, \ell}(1)} K$.  Let ${\textbf{P}}_1, \ldots, {\textbf{P}}_\ell\in{\mathbb Z}^D[z]$ be essentially distinct polynomials  with degrees at most $d$ and coefficients ${\textbf{P}}_j(z) = \sum_{i=0}^d {\boldsymbol{\beta}}_{ji} z^i$.
   Then for any $1$-bounded functions $f_0, \ldots,  f_\ell:{\mathbb Z}^D\to{\mathbb C}$, the lower bound  
			\begin{align*}
            \mathopen{}\left| \sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}
            f_0({\textbf{x}})\cdot f_1({\textbf{x}}+{\textbf{P}}_1(z))\cdots f_\ell({\textbf{x}}+{\textbf{P}}_\ell(z))\mathclose{}\right| \geq \delta N^D
			\end{align*}
   implies that
   \begin{align*}
       \mathbb{E}_{{\underline{h}}\in[\pm H]^{r}}\left\Vert f_1\right\Vert_{{{\textbf{C}}_1({\underline{h}})}\cdot[\pm M], \ldots, {{\textbf{C}}_s({\underline{h}})\cdot[\pm M]}}^{2^s} \gg_{d, D, \ell} \delta^{O_{d,\ell}(1)}N^D,
   \end{align*}
			where ${\textbf{C}}_1, \ldots, {\textbf{C}}_s\in{\mathbb Z}^D[{\underline{h}}]$ are nonzero multilinear polynomials depending only on ${\textbf{P}}_1, \ldots, {\textbf{P}}_\ell$, and they take the form
			\begin{align}
				{\textbf{C}}_{j}({\underline{h}}) = \sum_{\substack{{\underline{u}}\in \{0,1\}^{r},\\ |{\underline{u}}|\leq d-1}} (|{\underline{u}}|+1)! \cdot ({\boldsymbol{\beta}}_{1(|{\underline{u}}|+1)}-{\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+1)}){\underline{h}}^{\underline{u}}
			\end{align}
                for some indices $w_{j{\underline{u}}}\in[0,\ell]$ (with ${\boldsymbol{\beta}}_{0(|{\underline{u}}|+1)}:=\mathbf{0}$). Moreover, each nonzero vector ${\boldsymbol{\beta}}_{1(|{\underline{u}}|+1)}-{\boldsymbol{\beta}}_{w_{j{\underline{u}}}(|{\underline{u}}|+1)}$ from (29) is the leading coefficient of ${\textbf{P}}_1 - {\textbf{P}}_{w_{j{\underline{u}}}}$.

Let $d, \ell \in {\mathbb N}$.  There exists a positive integer $t=O_{d, \ell}(1)$ such that the following holds.  Let $D, K, N, V\in{\mathbb N}$ and $\delta>0$ satisfy $$\delta^{-O_{d,\ell}(1)}\ll_{d, D, \ell} K\ll_{d,D,\ell} (N/V)^{1/d},$$  and let ${\textbf{P}}_1, \ldots, {\textbf{P}}_\ell\in{\mathbb Z}^D[z]$ be polynomials of the form ${\textbf{P}}_j(z) = \sum_{i=0}^d {\boldsymbol{\beta}}_{ji}z^i$ with coefficients  at most $V$.\footnote{In the sense that for every $j,i$, each coordinate of ${\boldsymbol{\beta}}_{ji}$ is at most $V$ in absolute value, or equivalently that ${\boldsymbol{\beta}}_{ji}\in[\pm V]^D$.}
     Then for all $1$-bounded functions $f_0, \ldots, f_\ell:{\mathbb Z}^D\to{\mathbb C}$ supported on $[N]^D$, the bound
    \begin{align*}
            \mathopen{}\left| \sum_{{\textbf{x}}\in{\mathbb Z}^D}\mathbb{E}_{z\in[K]}
            f_0({\textbf{x}})\cdot f_1({\textbf{x}}+{\textbf{P}}_1(z))\cdots f_\ell({\textbf{x}}+{\textbf{P}}_\ell(z))\mathclose{}\right| \geq \delta N^D
    \end{align*}
    implies that
    \begin{align}
        \left\Vert f_j\right\Vert_{\{({\boldsymbol{\beta}}_{jd_{jj'}}-{\boldsymbol{\beta}}_{j'd_{jj'}})\cdot[\pm K^{d_{jj'}}]:\; j'\in[0,\ell],\; j'\neq j\}^{ t}}^{2^{\ell t}}\gg_{d, D, \ell}\delta^{O_{d, \ell}(1)}N^{D}
    \end{align}
    for all $j\in[0,\ell]$, where $d_{jj'} = \deg ({\textbf{P}}_j - {\textbf{P}}_{j'})$ and ${\textbf{P}}_0 = \mathbf{0}$.
